        pre = [0] * (n + 1)
        for i, c in enumerate(s):
            pre[i + 1] = pre[i] + (1 if c == '1' else -1)
        tz = s.count('0'); to = n - tz
        ans = 0
        for i in range(n):
            for j in range(i + 1, n + 1):
                b = pre[j] - pre[i]; L = j - i
                if b == 0:
                    ans = max(ans, L)
                elif abs(b) == 1 and L % 2 == 1:
