        for (int i = 0; i < n; i++) pre[i + 1] = pre[i] + (s[i] == '1' ? 1 : -1);
        int tz = count(s.begin(), s.end(), '0'), to = n - tz, ans = 0;
        unordered_map<int, int> first; first[0] = 0;
        for (int j = 1; j <= n; j++) {
            int d = pre[j];
            auto it = first.find(d);
            if (it != first.end()) ans = max(ans, j - it->second);
            for (int b : {1, -1}) {
                auto it2 = first.find(d - b);
                if (it2 != first.end()) {
                    int L = j - it2->second;
                    if (L % 2 == 1) {
                        int ones = (L + b) / 2, zeros = L - ones;
                        if ((b == 1 && tz > zeros) || (b == -1 && to > ones)) ans = max(ans, L);
                    }
                }
            }
            first.emplace(d, j);
        }
        return ans;
    }
};

